"""Move particles under their mutual gravity on the GPU and summarize the result.

Usage: uv run main.py <input-file>

Each step runs two compute kernels: one computes every particle's acceleration
from the positions at the start of the step, the other integrates velocity and
then position. Separate dispatches keep the first kernel's reads of positions
ordered before the second kernel's writes.
"""

import array
import math
import struct
import sys

import wgpu

WORKGROUP_SIZE = 64

SHADER = """
struct Params {
    n: u32,
    dt: f32,
    pad0: u32,
    pad1: u32,
};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read_write> pos: array<vec2<f32>>;
@group(0) @binding(2) var<storage, read_write> vel: array<vec2<f32>>;
@group(0) @binding(3) var<storage, read_write> acc: array<vec2<f32>>;

@compute @workgroup_size(%(wg)d)
fn accelerate(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.n) {
        return;
    }
    let pi = pos[i];
    var a = vec2<f32>(0.0, 0.0);
    for (var j: u32 = 0u; j < params.n; j = j + 1u) {
        // The j == i term is zero because the difference vector is zero.
        let d = pos[j] - pi;
        let r2 = dot(d, d) + 0.01;
        a = a + d / (r2 * sqrt(r2));
    }
    acc[i] = a;
}

@compute @workgroup_size(%(wg)d)
fn integrate(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.n) {
        return;
    }
    let v = vel[i] + acc[i] * params.dt;
    vel[i] = v;
    pos[i] = pos[i] + v * params.dt;
}
""" % {"wg": WORKGROUP_SIZE}


def read_input(path):
    with open(path, encoding="utf-8") as f:
        tokens = f.read().split()
    count, steps = int(tokens[0]), int(tokens[1])
    dt = float(tokens[2])
    values = [float(t) for t in tokens[3 : 3 + 4 * count]]
    xs = values[0::4]
    ys = values[1::4]
    vxs = values[2::4]
    vys = values[3::4]
    pos = []
    vel = []
    for i in range(count):
        pos.extend((xs[i], ys[i]))
        vel.extend((vxs[i], vys[i]))
    return count, steps, dt, pos, vel


def run_steps(count, steps, dt, pos_data, vel_data):
    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()

    storage = wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC
    pos_buf = device.create_buffer_with_data(
        data=array.array("f", pos_data),
        usage=storage | wgpu.BufferUsage.COPY_DST,
    )
    vel_buf = device.create_buffer_with_data(
        data=array.array("f", vel_data),
        usage=storage | wgpu.BufferUsage.COPY_DST,
    )
    acc_buf = device.create_buffer(size=count * 8, usage=storage)
    params_buf = device.create_buffer_with_data(
        data=struct.pack("<IfII", count, dt, 0, 0),
        usage=wgpu.BufferUsage.UNIFORM,
    )

    bind_layout = device.create_bind_group_layout(
        entries=[
            {
                "binding": 0,
                "visibility": wgpu.ShaderStage.COMPUTE,
                "buffer": {"type": wgpu.BufferBindingType.uniform},
            },
            {
                "binding": 1,
                "visibility": wgpu.ShaderStage.COMPUTE,
                "buffer": {"type": wgpu.BufferBindingType.storage},
            },
            {
                "binding": 2,
                "visibility": wgpu.ShaderStage.COMPUTE,
                "buffer": {"type": wgpu.BufferBindingType.storage},
            },
            {
                "binding": 3,
                "visibility": wgpu.ShaderStage.COMPUTE,
                "buffer": {"type": wgpu.BufferBindingType.storage},
            },
        ]
    )
    bind_group = device.create_bind_group(
        layout=bind_layout,
        entries=[
            {"binding": 0, "resource": {"buffer": params_buf, "offset": 0, "size": 16}},
            {"binding": 1, "resource": {"buffer": pos_buf, "offset": 0, "size": count * 8}},
            {"binding": 2, "resource": {"buffer": vel_buf, "offset": 0, "size": count * 8}},
            {"binding": 3, "resource": {"buffer": acc_buf, "offset": 0, "size": count * 8}},
        ],
    )
    pipeline_layout = device.create_pipeline_layout(bind_group_layouts=[bind_layout])

    module = device.create_shader_module(code=SHADER)
    accelerate = device.create_compute_pipeline(
        layout=pipeline_layout,
        compute={"module": module, "entry_point": "accelerate"},
    )
    integrate = device.create_compute_pipeline(
        layout=pipeline_layout,
        compute={"module": module, "entry_point": "integrate"},
    )

    groups = (count + WORKGROUP_SIZE - 1) // WORKGROUP_SIZE
    encoder = device.create_command_encoder()
    for _ in range(steps):
        for pipeline in (accelerate, integrate):
            citer = encoder.begin_compute_pass()
            citer.set_pipeline(pipeline)
            citer.set_bind_group(0, bind_group)
            citer.dispatch_workgroups(groups)
            citer.end()
    device.queue.submit([encoder.finish()])

    pos_out = array.array("f", bytes(device.queue.read_buffer(pos_buf)))
    vel_out = array.array("f", bytes(device.queue.read_buffer(vel_buf)))
    return pos_out, vel_out


def fmt(value):
    # Avoid printing "-0.000000" for values that round to zero.
    text = f"{value:.6f}"
    return "0.000000" if text == "-0.000000" else text


def summarize(count, pos, vel):
    xs = pos[0::2]
    ys = pos[1::2]
    vxs = vel[0::2]
    vys = vel[1::2]
    cx = math.fsum(xs) / count
    cy = math.fsum(ys) / count
    momentum_x = math.fsum(vxs)
    momentum_y = math.fsum(vys)
    kinetic = math.fsum((vx * vx + vy * vy) / 2.0 for vx, vy in zip(vxs, vys))
    spread = math.sqrt(
        math.fsum((x - cx) ** 2 + (y - cy) ** 2 for x, y in zip(xs, ys)) / count
    )
    return [
        f"CENTER {fmt(cx)} {fmt(cy)}",
        f"MOMENTUM {fmt(momentum_x)} {fmt(momentum_y)}",
        f"KINETIC {fmt(kinetic)}",
        f"SPREAD {fmt(spread)}",
    ]


def main(argv):
    if len(argv) < 2:
        print("usage: main.py <input-file>", file=sys.stderr)
        return 2
    count, steps, dt, pos, vel = read_input(argv[1])
    if steps > 0:
        pos, vel = run_steps(count, steps, dt, pos, vel)
    else:
        pos = array.array("f", pos)
        vel = array.array("f", vel)
    for line in summarize(count, pos, vel):
        print(line)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

