    params_buf = device.create_buffer_with_data(
        data=struct.pack("<IfII", count, dt, 0, 0),
        usage=wgpu.BufferUsage.UNIFORM,
    )

    bind_layout = device.create_bind_group_layout(
        entries=[
            {
                "binding": 0,
                "visibility": wgpu.ShaderStage.COMPUTE,
                "buffer": {"type": wgpu.BufferBindingType.uniform},
            },
            {
                "binding": 1,
                "visibility": wgpu.ShaderStage.COMPUTE,
                "buffer": {"type": wgpu.BufferBindingType.storage},
            },
            {
                "binding": 2,
                "visibility": wgpu.ShaderStage.COMPUTE,
                "buffer": {"type": wgpu.BufferBindingType.storage},
            },
            {
                "binding": 3,
                "visibility": wgpu.ShaderStage.COMPUTE,
                "buffer": {"type": wgpu.BufferBindingType.storage},
            },
        ]
    )
    bind_group = device.create_bind_group(
        layout=bind_layout,
        entries=[
            {"binding": 0, "resource": {"buffer": params_buf, "offset": 0, "size": 16}},
            {"binding": 1, "resource": {"buffer": pos_buf, "offset": 0, "size": count * 8}},
            {"binding": 2, "resource": {"buffer": vel_buf, "offset": 0, "size": count * 8}},
            {"binding": 3, "resource": {"buffer": acc_buf, "offset": 0, "size": count * 8}},
        ],
    )
    pipeline_layout = device.create_pipeline_layout(bind_group_layouts=[bind_layout])

    module = device.create_shader_module(code=SHADER)
    accelerate = device.create_compute_pipeline(
        layout=pipeline_layout,
        compute={"module": module, "entry_point": "accelerate"},
    )
    integrate = device.create_compute_pipeline(
        layout=pipeline_layout,
        compute={"module": module, "entry_point": "integrate"},
    )

    groups = (count + WORKGROUP_SIZE - 1) // WORKGROUP_SIZE
    encoder = device.create_command_encoder()
    for _ in range(steps):
        for pipeline in (accelerate, integrate):
            citer = encoder.begin_compute_pass()
            citer.set_pipeline(pipeline)
            citer.set_bind_group(0, bind_group)
            citer.dispatch_workgroups(groups)
            citer.end()
    device.queue.submit([encoder.finish()])

    pos_out = array.array("f", bytes(device.queue.read_buffer(pos_buf)))
    vel_out = array.array("f", bytes(device.queue.read_buffer(vel_buf)))
    return pos_out, vel_out


def fmt(value):
    # Avoid printing "-0.000000" for values that round to zero.
    text = f"{value:.6f}"
    return "0.000000" if text == "-0.000000" else text


def summarize(count, pos, vel):
    xs = pos[0::2]
    ys = pos[1::2]
    vxs = vel[0::2]
    vys = vel[1::2]
    cx = math.fsum(xs) / count
    cy = math.fsum(ys) / count
    momentum_x = math.fsum(vxs)
    momentum_y = math.fsum(vys)
    kinetic = math.fsum((vx * vx + vy * vy) / 2.0 for vx, vy in zip(vxs, vys))
    spread = math.sqrt(
        math.fsum((x - cx) ** 2 + (y - cy) ** 2 for x, y in zip(xs, ys)) / count
    )
    return [
        f"CENTER {fmt(cx)} {fmt(cy)}",
        f"MOMENTUM {fmt(momentum_x)} {fmt(momentum_y)}",
        f"KINETIC {fmt(kinetic)}",
        f"SPREAD {fmt(spread)}",
    ]


def main(argv):
    if len(argv) < 2:
        print("usage: main.py <input-file>", file=sys.stderr)
        return 2
    count, steps, dt, pos, vel = read_input(argv[1])
    if steps > 0:
        pos, vel = run_steps(count, steps, dt, pos, vel)
    else:
        pos = array.array("f", pos)
        vel = array.array("f", vel)
    for line in summarize(count, pos, vel):
        print(line)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
